import{_ as i,c as e,o as a,az as n}from"./chunks/framework.BFtVSaaV.js";const p=JSON.parse('{"title":"Welcome to AdditionalDistributions.jl","description":"","frontmatter":{"layout":"home","hero":{"name":"AdditionalDistributions.jl","text":null,"tagline":"An extension of Distributions.jl package.","image":{"src":"logo.png","alt":"AdditionalDistributions.jl"},"actions":[{"theme":"brand","text":"Getting started","link":"getting_started"},{"theme":"alt","text":"View on Github","link":"https://github.com/Santymax98/AdditionalDistributions.jl"},{"theme":"alt","text":"Bestiary","link":"/bestiary/continuous"}]}},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),o={name:"index.md"};function s(r,t,l,d,m,u){return a(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="Welcome-to-AdditionalDistributions.jl" tabindex="-1">Welcome to AdditionalDistributions.jl <a class="header-anchor" href="#Welcome-to-AdditionalDistributions.jl" aria-label="Permalink to &quot;Welcome to AdditionalDistributions.jl {#Welcome-to-AdditionalDistributions.jl}&quot;">​</a></h1><p>The <a href="https://github.com/Santymax98/AdditionalDistributions.jl" target="_blank" rel="noreferrer"><em>AdditionalDistributions.jl</em></a> package is a comprehensive extension of <a href="https://github.com/JuliaStats/Distributions.jl" target="_blank" rel="noreferrer"><em>Distributions.jl</em></a>, designed to expand its functionality by incorporating both discrete and continuous probability distributions not available in the base package. <em>AdditionalDistributions</em> aims to enhance the breadth of statistical tools available for data analysis, simulation, and probabilistic modeling.</p><p>With <em>AdditionalDistributions</em>, you can:</p><ul><li><p><strong>Sample from distributions:</strong> Draw random samples from a variety of distributions.</p></li><li><p><strong>Calculate moments and other properties:</strong> Obtain moments (such as mean, variance, skewness, and kurtosis), entropy, and other statistical properties.</p></li><li><p><strong>Evaluate probability density/mass functions:</strong> Compute the probability density functions (pdf) and their logarithms (logpdf).</p></li><li><p><strong>Utilize moment-generating, quantile, and characteristic functions:</strong> Access moment-generating functions, quantile functions, and characteristic functions for in-depth statistical analysis.</p></li></ul><p>In the future, we plan to implement maximum likelihood estimators and potentially introduce additional multivariate distributions to further enrich the package. Collaborators are also welcome.</p>',5)])])}const b=i(o,[["render",s]]);export{p as __pageData,b as default};
